public struct MetricBoxDistribution: Codable, Equatable, Sendable {
  public var kind: String
  /// null when the group has no numeric samples.
  public var summary: MetricBoxSummary?
  enum CodingKeys: String, CodingKey {
    case kind
    case summary
  }
  public init(summary: MetricBoxSummary? = nil) {
    self.kind = "box"
