    let c = try decoder.container(keyedBy: CodingKeys.self)
    kind = try c.decode(String.self, forKey: .kind)
    guard kind == "box" else {
      throw DecodingError.dataCorruptedError(forKey: .kind, in: c, debugDescription: "Expected box")
    }
    summary = try c.decodeNil(forKey: .summary) ? nil : try c.decode(MetricBoxSummary.self, forKey: .summary)
  }
  public func encode(to encoder: Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(kind, forKey: .kind)
    if let v = summary { try c.encode(v, forKey: .summary) } else { try c.encodeNil(forKey: .summary) }
  }
}

