  public init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    sourceTotal = try c.decode(Int.self, forKey: .sourceTotal)
    version = try c.decode(Int.self, forKey: .version)
    now = try c.decode(Int64.self, forKey: .now)
    rows = try c.decode([[String: JSONValue]].self, forKey: .rows)
    total = try c.decode(Int.self, forKey: .total)
    schema = try c.decode(ProjectedSchemaV3.self, forKey: .schema)
    metrics = try c.decode([AggregationResultEntry].self, forKey: .metrics)
    execution = try c.decode(QueryExecutionV3.self, forKey: .execution)
    distinct = try c.decodeIfPresent(DistinctResultV3.self, forKey: .distinct)
  }
  public func encode(to encoder: Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(sourceTotal, forKey: .sourceTotal)
    try c.encode(version, forKey: .version)
    try c.encode(now, forKey: .now)
    try c.encode(rows, forKey: .rows)
    try c.encode(total, forKey: .total)
    try c.encode(schema, forKey: .schema)
    try c.encode(metrics, forKey: .metrics)
    try c.encode(execution, forKey: .execution)
    try c.encodeIfPresent(distinct, forKey: .distinct)
  }
}

/// One stage (source or result) of a request. It has exactly these keys; view-only state never crosses the wire.
public struct ServerQuery: Codable, Equatable, Sendable {
  /// Field names to return.
  public var select: [String]
  /// Pushdown predicates (CNF).
  public var whereTerms: [WhereTerm]
  /// Server-sortable terms, remapped through FieldDef.sort.field.
  public var orderBy: [OrderByClause]
  public var limit: Int
  public var offset: Int
  enum CodingKeys: String, CodingKey {
    case select
    case whereTerms = "where"
    case orderBy
    case limit
    case offset
  }
  public init(select: [String] = [], whereTerms: [WhereTerm] = [], orderBy: [OrderByClause] = [], limit: Int = 100, offset: Int = 0) {
    self.select = select
    self.whereTerms = whereTerms
    self.orderBy = orderBy
    self.limit = limit
    self.offset = offset
  }
  public init(from decoder: Decoder) throws {
    let c = try decoder.container(keyedBy: CodingKeys.self)
    select = try c.decode([String].self, forKey: .select)
    whereTerms = try c.decode([WhereTerm].self, forKey: .whereTerms)
    orderBy = try c.decode([OrderByClause].self, forKey: .orderBy)
    limit = try c.decode(Int.self, forKey: .limit)
    offset = try c.decode(Int.self, forKey: .offset)
  }
  public func encode(to encoder: Encoder) throws {
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(select, forKey: .select)
    try c.encode(whereTerms, forKey: .whereTerms)
    try c.encode(orderBy, forKey: .orderBy)
    try c.encode(limit, forKey: .limit)
    try c.encode(offset, forKey: .offset)
  }
}
